// Revisão editorial explícita. Tuplas: fonte, âncora, cenário, gabarito, distratores.
// Não publicar sem validação no manifesto. Caminhos correspondem às aulas citadas.
export const proposals = {};
const set = (title, rows) => { proposals[title] = rows.map(([source, anchor, prompt, correct, wrong]) => ({ source, anchor, prompt, correct, wrong: wrong.split('|') })); };

